-- solucao e backup ensino.turma e ensino.matricula_componente
WITH turmas_series_atualizar AS (
	SELECT DISTINCT ts.id_turma_serie
	FROM basico.turma_serie ts 
	WHERE TRUE AND ts.id_curriculo_medio IN (55273207, 55286341, 55286367) AND ts.ativo = TRUE
), componentes_inserir AS (
	SELECT DISTINCT cbc.id_componente_curricular, cbc.ordem, cbc.id_categoria_componente
	FROM basico.curriculo_basico_componente cbc 
	WHERE cbc.id_curriculo_basico IN (55273207, 55286341, 55286367)
), turmas_referencia AS (
	SELECT DISTINCT t.ano, t.periodo, t.id_situacao_turma, t.capacidade_aluno, t.codigo, t.tipo, t.id_turma_agrupadora, t.agrupadora, t.id_turma_serie, t.nota, t.extra
	FROM ensino.turma t 
	JOIN turmas_series_atualizar tsa ON t.id_turma_serie = tsa.id_turma_serie
	WHERE t.id_disciplina = 507
), dados_inserir_turma_componente AS (
	SELECT DISTINCT nextval('ensino.turma_seq') AS id_turma, current_date AS data_cadastro, ci.*, tr.* 
	FROM turmas_referencia tr, componentes_inserir ci
	WHERE ci.id_componente_curricular NOT IN (SELECT t.id_disciplina FROM ensino.turma t JOIN turmas_series_atualizar tsa ON t.id_turma_serie = tsa.id_turma_serie)
	ORDER BY ci.id_componente_curricular, tr.codigo
), script_inserir_turma_componente AS (
	SELECT DISTINCT 'INSERT INTO ensino.turma (id_turma, data_cadastro, id_disciplina, ano, periodo, id_situacao_turma, capacidade_aluno, codigo, tipo, id_turma_agrupadora, agrupadora, id_turma_serie, nota, extra, ordem, id_categoria_componente) VALUES (' || id_turma || ', ''' || data_cadastro || ''', ' || id_componente_curricular || ', ' || ano || ', ' || periodo || ', ' || id_situacao_turma || ', ' || capacidade_aluno || ', ''' || codigo || ''', ' || tipo || ', ' || id_turma_agrupadora || ', ' || agrupadora || ', ' || id_turma_serie || ', ' || nota || ', ' || extra  || ', ' || ordem || ', ' || id_categoria_componente || ');' AS solucao, 'DELETE FROM ensino.turma WHERE id_turma = ' || id_turma || ';' AS bakcup
	FROM dados_inserir_turma_componente
), matriculas_referencia AS (
	SELECT DISTINCT t.id_turma_serie, mc.id_situacao_matricula, mc.id_discente, mc.media_final, mc.ano, mc.periodo, mc.prova_especial, mc.id_tipo_matricula_componente, mc.ausente_recuperacao, mc.nao_optou, mc.conselho_classe, mc.id_matricula_estudante_serie, mc.avaliacao_por_conceito
	FROM basico.matricula_estudante_serie mes 
	JOIN turmas_series_atualizar tsa ON tsa.id_turma_serie = COALESCE(mes.id_turma_serie_multisseriado, mes.id_turma_serie)
	JOIN ensino.turma t ON t.id_turma_serie = tsa.id_turma_serie
	JOIN ensino.matricula_componente mc ON mc.id_turma = t.id_turma AND mc.id_discente = mes.id_estudante
	WHERE mc.id_componente_curricular = 507 AND mes.id_situacao_matricula_serie IN (1, 2, 3) AND mc.id_situacao_matricula NOT IN (3, 4, 7, 9, 11)
), dados_inserir_matricula_componente AS (
	SELECT DISTINCT nextval('ensino.matricula_componente_seq') AS id_matricula_componente, current_date AS data_cadastro, ditc.id_turma, ditc.id_componente_curricular, mr.*
	FROM matriculas_referencia mr, dados_inserir_turma_componente ditc
	WHERE mr.id_turma_serie = ditc.id_turma_serie
	ORDER BY mr.id_discente, ditc.id_componente_curricular
), script_inserir_matricula_componente AS (
	SELECT DISTINCT 'INSERT INTO ensino.matricula_componente (id_matricula_componente, data_cadastro, id_turma, id_componente_curricular, id_situacao_matricula, id_discente, media_final, ano, periodo, prova_especial, id_tipo_matricula_componente, ausente_recuperacao, nao_optou, conselho_classe, id_matricula_estudante_serie, avaliacao_por_conceito) VALUES (' || id_matricula_componente || ', ''' || data_cadastro || ''', ' || id_turma || ', ' || id_componente_curricular || ', ' || id_situacao_matricula || ', ' || id_discente || ', ' || media_final || ', ' || ano || ', ' || periodo || ', ' || prova_especial || ', ' || id_tipo_matricula_componente || ', ' || ausente_recuperacao || ', ' || nao_optou || ', ' || conselho_classe || ', ' || id_matricula_estudante_serie || ', ' || avaliacao_por_conceito || ');' AS solucao, 'DELETE FROM ensino.matricula_componente WHERE id_matricula_componente = ' || id_matricula_componente || ';' AS bakcup
	FROM dados_inserir_matricula_componente
) SELECT DISTINCT * FROM script_inserir_turma_componente UNION ALL SELECT DISTINCT * FROM script_inserir_matricula_componente;

-- backup basico.curriculo_basico_componente
SELECT 'DELETE FROM basico.curriculo_basico_componente WHERE id_curriculo_basico_componente = ' || cbc.id_curriculo_basico_componente || ';' FROM basico.curriculo_basico_componente cbc WHERE cbc.id_curriculo_basico IN (55286367, 55286341, 55273207) AND cbc.id_componente_curricular IN (221, 222, 223, 224, 225, 229, 230, 238);